/** Catalogue keyed by id, e.g. SIGNS.speed_30. Diagram numbers are how lessons refer to signs. */
export const SIGNS = Object.fromEntries(SIGN_LIST.map((s) => [s.id, s]));

/** Diagram number -> id (first match), e.g. byDiagram("670") -> "speed_20". */
export function byDiagram(d) { return SIGN_LIST.find((s) => s.diagram === String(d))?.id; }
